// Interval (ms) between clipboard polls — VS Code has no native clipboard-change event
const CLIPBOARD_POLL_INTERVAL_MS = 500;

// This method is called when your extension is activated
// Your extension is activated the very first time the command is executed
export function activate(context: vscode.ExtensionContext) {

	// Use the console to output diagnostic information (console.log) and errors (console.error)
	// This line of code will only be executed once when your extension is activated
	console.log('Congratulations, your extension "my-vs-code-extension" is now active!');

	// The command has been defined in the package.json file
	// Now provide the implementation of the command with registerCommand
	// The commandId parameter must match the command field in package.json
	const disposable = vscode.commands.registerCommand('my-vs-code-extension.helloWorld', () => {
		// The code you place here will be executed every time your command is executed
		// Display a message box to the user
		vscode.window.showInformationMessage('Hello World from My VS Code Extension!');
	});

	context.subscriptions.push(disposable);

	// --- Clipboard Monitor ---
	// VS Code does not expose a native clipboard-change event, so we poll
	// vscode.env.clipboard.readText() on a fixed interval and fire whenever
	// the content differs from the last known value.

	let lastClipboardContent: string | undefined;

	async function checkClipboard(): Promise<void> {
		try {
			const current = await vscode.env.clipboard.readText();
			if (lastClipboardContent === undefined) {
				// First read — establish baseline without firing the handler
				lastClipboardContent = current;
				return;
			}
			if (current !== lastClipboardContent) {
				lastClipboardContent = current;
				onClipboardChanged(current);
			}
		} catch (err) {
			console.error('[clipboard-monitor] Error reading clipboard:', err);
		}
	}

	/**
	 * Called every time the clipboard content changes.
	 * Replace or extend this handler with your own logic.
	 */
	function onClipboardChanged(text: string): void {
		console.log('[clipboard-monitor] Clipboard changed:', text);
		vscode.window.showInformationMessage(
			`📋 Clipboard updated: ${text.length > 60 ? text.slice(0, 60) + '…' : text}`
		);
	}

	// Kick off the polling loop and register cleanup so it stops on deactivation
	const clipboardTimer = setInterval(checkClipboard, CLIPBOARD_POLL_INTERVAL_MS);

	context.subscriptions.push({
		dispose: () => clearInterval(clipboardTimer),
	});
}

