/**
 * apiKeyDetector.ts
 *
 * Detects strings that match common API key / secret formats.
 * Each rule has a human-readable label, a regex, and an optional
 * entropy guard to reduce false-positives.
 */

export interface ApiKeyMatch {
	/** Human-readable name of the detected key type */
	label: string;
	/** The matched substring */
	match: string;
	/** Approximate Shannon entropy of the matched value (bits/char) */
	entropy: number;
}

// ---------------------------------------------------------------------------
// Pattern registry
// ---------------------------------------------------------------------------

interface DetectorRule {
	label: string;
	/** Applied to the full clipboard text; uses global flag to find all occurrences */
	pattern: RegExp;
	/**
	 * Minimum Shannon entropy (bits per character) required to accept the match.
	 * Helps reject low-entropy placeholders like "XXXXXXXXXXXXXXXX".
	 * Set to 0 to disable the entropy check for a rule.
	 */
	minEntropy: number;
}

const RULES: DetectorRule[] = [
	// ── Cloud providers ────────────────────────────────────────────────────
	{
		label: 'AWS Access Key ID',
		pattern: /\b(A(?:KIA|SIA|ROA|IDA)[0-9A-Z]{16})\b/g,
		minEntropy: 3.0,
	},
	{
		label: 'AWS Secret Access Key',
		// 40-char base62 string that often follows "aws_secret" context;
		// we match the value shape broadly and rely on entropy to filter.
		pattern: /\b([A-Za-z0-9/+=]{40})\b/g,
		minEntropy: 4.5,
	},
	{
		label: 'Google API Key',
		pattern: /\b(AIza[0-9A-Za-z\-_]{35})\b/g,
		minEntropy: 3.5,
	},
	{
		label: 'Google OAuth Client Secret',
		pattern: /\b(GOCSPX-[0-9A-Za-z\-_]{28})\b/g,
		minEntropy: 3.5,
	},
	{
		label: 'Firebase API Key',
		// Firebase keys look identical to generic Google API keys
		pattern: /\b(AIza[0-9A-Za-z\-_]{35})\b/g,
		minEntropy: 3.5,
	},

	// ── Source control & CI ────────────────────────────────────────────────
	{
		label: 'GitHub Personal Access Token (classic)',
		pattern: /\b(ghp_[A-Za-z0-9]{36})\b/g,
		minEntropy: 3.5,
	},
	{
		label: 'GitHub Fine-Grained PAT',
		pattern: /\b(github_pat_[A-Za-z0-9_]{82})\b/g,
		minEntropy: 3.5,
	},
	{
		label: 'GitHub OAuth Token',
		pattern: /\b(gho_[A-Za-z0-9]{36})\b/g,
		minEntropy: 3.5,
	},
	{
		label: 'GitHub App Token',
		pattern: /\b(ghs_[A-Za-z0-9]{36})\b/g,
		minEntropy: 3.5,
	},
	{
		label: 'GitHub Refresh Token',
		pattern: /\b(ghr_[A-Za-z0-9]{36})\b/g,
		minEntropy: 3.5,
	},
	{
		label: 'GitLab Personal Access Token',
		pattern: /\b(glpat-[A-Za-z0-9\-_]{20})\b/g,
		minEntropy: 3.5,
	},

	// ── Payment & commerce ─────────────────────────────────────────────────
	{
		label: 'Stripe Secret Key',
		pattern: /\b(sk_(?:live|test)_[0-9A-Za-z]{24,})\b/g,
		minEntropy: 3.5,
	},
	{
		label: 'Stripe Publishable Key',
		pattern: /\b(pk_(?:live|test)_[0-9A-Za-z]{24,})\b/g,
		minEntropy: 3.5,
	},
	{
		label: 'Stripe Restricted Key',
		pattern: /\b(rk_(?:live|test)_[0-9A-Za-z]{24,})\b/g,
		minEntropy: 3.5,
	},
	{
		label: 'PayPal / Braintree Access Token',
		pattern: /\b(access_token\$production\$[0-9a-z]{16}\$[0-9a-f]{32})\b/g,
		minEntropy: 3.5,
	},

	// ── Communication ──────────────────────────────────────────────────────
	{
		label: 'Twilio Account SID',
		pattern: /\b(AC[a-f0-9]{32})\b/g,
		minEntropy: 3.0,
	},
	{
		label: 'Twilio Auth Token',
		pattern: /\b([a-f0-9]{32})\b/g,
		minEntropy: 3.8,
	},
	{
		label: 'SendGrid API Key',
		pattern: /\b(SG\.[A-Za-z0-9\-_]{22}\.[A-Za-z0-9\-_]{43})\b/g,
		minEntropy: 3.5,
	},
	{
		label: 'Mailgun API Key',
		pattern: /\b(key-[0-9a-f]{32})\b/g,
		minEntropy: 3.5,
	},

	// ── AI / ML platforms ──────────────────────────────────────────────────
	{
		label: 'OpenAI API Key',
		pattern: /\b(sk-(?:proj-)?[A-Za-z0-9]{32,})\b/g,
		minEntropy: 3.5,
	},
	{
		label: 'Anthropic API Key',
		pattern: /\b(sk-ant-(?:api\d{2}-)?[A-Za-z0-9\-_]{93,})\b/g,
		minEntropy: 3.5,
	},
	{
		label: 'Hugging Face API Token',
		pattern: /\b(hf_[A-Za-z0-9]{34,})\b/g,
		minEntropy: 3.5,
	},

	// ── Infrastructure & secrets managers ─────────────────────────────────
	{
		label: 'HashiCorp Vault Token',
		pattern: /\b(hvs\.[A-Za-z0-9]{24,})\b/g,
		minEntropy: 3.5,
	},
	{
		label: 'npm Auth Token',
		pattern: /\b(npm_[A-Za-z0-9]{36})\b/g,
		minEntropy: 3.5,
	},
	{
		label: 'Slack Bot / App Token',
		pattern: /\b(xox[baprs]-[0-9A-Za-z\-]{10,})\b/g,
		minEntropy: 3.5,
	},
	{
		label: 'Slack Webhook URL',
		pattern: /(https:\/\/hooks\.slack\.com\/services\/T[A-Z0-9]+\/B[A-Z0-9]+\/[A-Za-z0-9]+)/g,
		minEntropy: 3.0,
	},

	// ── Generic high-entropy secrets ───────────────────────────────────────
	{
		label: 'Generic hex secret (32 chars)',
		pattern: /\b([0-9a-fA-F]{32})\b/g,
		minEntropy: 3.8,
	},
	{
		label: 'Generic hex secret (64 chars)',
		pattern: /\b([0-9a-fA-F]{64})\b/g,
		minEntropy: 3.8,
	},
	{
		label: 'Generic base64 secret (≥32 chars)',
		pattern: /\b([A-Za-z0-9+/]{32,}={0,2})\b/g,
		minEntropy: 4.8,
	},
];

// ---------------------------------------------------------------------------
// Shannon entropy helper
// ---------------------------------------------------------------------------

/**
 * Computes the Shannon entropy of a string in bits per character.
 * Higher values → more random-looking → more likely to be a real secret.
 */
function shannonEntropy(s: string): number {
	if (s.length === 0) { return 0; }
	const freq = new Map<string, number>();
	for (const ch of s) {
		freq.set(ch, (freq.get(ch) ?? 0) + 1);
	}
	let entropy = 0;
	for (const count of freq.values()) {
		const p = count / s.length;
		entropy -= p * Math.log2(p);
	}
	return entropy;
}

// ---------------------------------------------------------------------------
// Public API
// ---------------------------------------------------------------------------

/**
 * Scans `text` against every registered rule and returns all matches that
 * pass the entropy threshold.  Duplicate match strings are deduplicated.
 */
export function detectApiKeys(text: string): ApiKeyMatch[] {
	const seen = new Set<string>();
	const results: ApiKeyMatch[] = [];

	for (const rule of RULES) {
		// Reset lastIndex because we reuse compiled regexes (global flag)
		rule.pattern.lastIndex = 0;

		let m: RegExpExecArray | null;
		while ((m = rule.pattern.exec(text)) !== null) {
			const value = m[1] ?? m[0];
			if (seen.has(value)) { continue; }

			const entropy = shannonEntropy(value);
			if (entropy < rule.minEntropy) { continue; }

			seen.add(value);
			results.push({ label: rule.label, match: value, entropy });
		}
	}

	return results;
}

// The module 'vscode' contains the VS Code extensibility API
// Import the module and reference it with the alias vscode in your code below
import * as vscode from 'vscode';
import { detectApiKeys, ApiKeyMatch } from './apiKeyDetector';

// Interval (ms) between clipboard polls — VS Code has no native clipboard-change event
const CLIPBOARD_POLL_INTERVAL_MS = 500;

// This method is called when your extension is activated
// Your extension is activated the very first time the command is executed
export function activate(context: vscode.ExtensionContext) {

	console.log('Congratulations, your extension "my-vs-code-extension" is now active!');

	// ── Hello World command ────────────────────────────────────────────────
	const disposable = vscode.commands.registerCommand('my-vs-code-extension.helloWorld', () => {
		vscode.window.showInformationMessage('Hello World from My VS Code Extension!');
	});
	context.subscriptions.push(disposable);

	// ── Clipboard Monitor ──────────────────────────────────────────────────
	// VS Code has no native clipboard-change event, so we poll on a fixed
	// interval and fire onClipboardChanged() whenever the content differs.

	let lastClipboardContent: string | undefined;

	async function checkClipboard(): Promise<void> {
		try {
			const current = await vscode.env.clipboard.readText();
			if (lastClipboardContent === undefined) {
				// First read — establish baseline silently
				lastClipboardContent = current;
				return;
			}
			if (current !== lastClipboardContent) {
				lastClipboardContent = current;
				onClipboardChanged(current);
			}
		} catch (err) {
			console.error('[clipboard-monitor] Error reading clipboard:', err);
		}
	}

	/**
	 * Fired on every clipboard change.
	 * Runs the API-key filter and surfaces any matches to the user.
	 */
	function onClipboardChanged(text: string): void {
		console.log('[clipboard-monitor] Clipboard changed:', text);

		const matches = detectApiKeys(text);

		if (matches.length === 0) {
			// Plain clipboard update — no secrets detected
			vscode.window.showInformationMessage(
				`📋 Clipboard updated: ${text.length > 60 ? text.slice(0, 60) + '…' : text}`
			);
			return;
		}

		// One or more potential API keys detected
		handleApiKeyDetected(text, matches);
	}

	/**
	 * Called when the clipboard contains one or more strings that look like
	 * API keys / secrets.  Shows a warning with details and offers to clear
	 * the clipboard.
	 */
	function handleApiKeyDetected(text: string, matches: ApiKeyMatch[]): void {
		const summary = matches
			.map(m => `• ${m.label}  [entropy: ${m.entropy.toFixed(2)} bits/char]`)
			.join('\n');

		console.warn('[clipboard-monitor] ⚠️  Potential API key(s) detected:\n' + summary);

		// Truncate the raw value shown in the notification for safety
		const preview = matches[0].match.length > 20
			? matches[0].match.slice(0, 10) + '…' + matches[0].match.slice(-4)
			: matches[0].match;

		const label = matches.length === 1
			? `⚠️ API key detected: ${matches[0].label} (${preview})`
			: `⚠️ ${matches.length} potential secrets detected in clipboard`;

		vscode.window
			.showWarningMessage(label, 'Show Details', 'Clear Clipboard', 'Dismiss')
			.then(selection => {
				if (selection === 'Show Details') {
					// Surface full match list in the output channel
					const channel = vscode.window.createOutputChannel('API Key Monitor');
					channel.clear();
					channel.appendLine('⚠️  Potential secrets detected in clipboard\n');
					channel.appendLine(`Clipboard length: ${text.length} characters`);
					channel.appendLine(`Detected matches (${matches.length}):\n`);
					matches.forEach((m, i) => {
						const redacted = m.match.slice(0, 6) + '…' + m.match.slice(-4);
						channel.appendLine(`  [${i + 1}] ${m.label}`);
						channel.appendLine(`      Value (redacted): ${redacted}`);
						channel.appendLine(`      Entropy:          ${m.entropy.toFixed(3)} bits/char\n`);
					});
					channel.show(true);
				} else if (selection === 'Clear Clipboard') {
					vscode.env.clipboard.writeText('').then(() => {
						lastClipboardContent = '';
						vscode.window.showInformationMessage('✅ Clipboard cleared.');
					});
				}
			});
	}

	// Kick off polling; register cleanup so the interval stops on deactivation
	const clipboardTimer = setInterval(checkClipboard, CLIPBOARD_POLL_INTERVAL_MS);
	context.subscriptions.push({ dispose: () => clearInterval(clipboardTimer) });
}

// This method is called when your extension is deactivated
export function deactivate() {}

